class DataProcessor:
    def __init__(self, batch_size=10):
        self.buffer = []
        self.count = 0
        self.batch_size = batch_size

    def process(self, record):
        self.buffer.append(record)
        self.count += 1
        if self.count >= self.batch_size:
            self.flush()

    def flush(self):
        for item in self.buffer:
            write_output(item)
        self.buffer.clear()
        self.count = 0

    def status(self):
        return f'buffered={self.count}, batch={self.batch_size}'

def write_output(item):
    print(f'[OUT] {item}')

def compute_metrics(data):
    if not data:
        return {'total': 0, 'mean': 0, 'variance': 0}
    total = sum(data)
    mean = total / len(data)
    variance = sum((x - mean)**2 for x in data) / len(data)
    return {'total': total, 'mean': mean, 'variance': variance}

def filter_outliers(data, threshold=2.5):
    if len(data) < 3:
        return data
    mean = sum(data) / len(data)
    std = (sum((x-mean)**2 for x in data) / len(data)) ** 0.5
    return [x for x in data if abs(x - mean) <= threshold * std]

def normalize(data):
    mn = min(data)
    mx = max(data)
    rng = mx - mn
    return [(x - mn) / rng for x in data] if rng > 0 else data

class EventLoop:
    def __init__(self, max_depth=100):
        self.handlers = {}
        self.queue = []
        self.max_depth = max_depth
        self.depth = 0

    def register(self, event_type, handler):
        self.handlers[event_type] = handler

    def emit(self, event_type, payload):
        self.queue.append((event_type, payload))

    def tick(self):
        self.depth = 0
        while self.queue and self.depth < self.max_depth:
            etype, payload = self.queue.pop(0)
            if etype in self.handlers:
                self.handlers[etype](payload)
            self.depth += 1

def compute_metrics(data):
    if not data:
        return {'total': 0, 'mean': 0, 'variance': 0}
    total = sum(data)
    n = len(data)
    mean = total / n
    variance = sum((x - mean)**2 for x in data) / (n - 1)
    std_dev = variance ** 0.5
    return {'total': total, 'mean': mean, 'variance': variance, 'std': std_dev}
